package com.nook.phone;
import android.app.PendingIntent;import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;
public class NookWidget extends AppWidgetProvider {
    public static void update(Context c,String status){c.getSharedPreferences("nook",0).edit().putString("status",status).putInt("active",0).putBoolean("waiting",false).apply();AppWidgetManager m=AppWidgetManager.getInstance(c);Class<?>[] types={NookWidget.class,PetWidget.class,AgentsWidget.class,RequestsWidget.class};String[] kinds={"status","pet","agents","requests"};for(int i=0;i<types.length;i++)renderVariant(c,m,m.getAppWidgetIds(new ComponentName(c,types[i])),status,kinds[i]);}
    private static void render(Context c,AppWidgetManager m,int[] ids,String status){renderVariant(c,m,ids,status,"status");}
    public static void updateState(Context c,org.json.JSONObject state){int active=0;org.json.JSONArray sessions=state.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){org.json.JSONObject s=sessions.optJSONObject(i);if(s!=null&&!s.optBoolean("finished"))active++;}boolean waiting=state.optJSONObject("pending")!=null;String copy=waiting?"Review needed":active>0?active+" agents working":"All quiet";c.getSharedPreferences("nook",0).edit().putString("status",copy).putInt("active",active).putBoolean("waiting",waiting).apply();AppWidgetManager m=AppWidgetManager.getInstance(c);Class<?>[] types={NookWidget.class,PetWidget.class,AgentsWidget.class,RequestsWidget.class};String[] variants={"status","pet","agents","requests"};for(int i=0;i<types.length;i++)renderVariant(c,m,m.getAppWidgetIds(new ComponentName(c,types[i])),copy,variants[i]);}
    protected static void renderVariant(Context c,AppWidgetManager m,int[] ids,String status,String kind){int layout=kind.equals("pet")?R.layout.widget_pet:R.layout.widget;RemoteViews view=new RemoteViews(c.getPackageName(),layout);boolean waiting=c.getSharedPreferences("nook",0).getBoolean("waiting",false);int active=c.getSharedPreferences("nook",0).getInt("active",0);String copy=status.equals("Disconnected")?status:kind.equals("agents")?active+" active agents":kind.equals("requests")?(waiting?"Request needs review":"No waiting requests"):status;if(!kind.equals("pet"))view.setTextViewText(R.id.widget_status,copy);view.setInt(R.id.widget_root,"setBackgroundColor",waiting?0xff38291b:active>0?0xff172a3e:0xff152b25);view.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));for(int id:ids)m.updateAppWidget(id,view);}
    @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){render(c,m,ids,c.getSharedPreferences("nook",0).getString("status","Open Nook to connect"));}
}
